import {
  createElement,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
  useRef,
} from "react";
import { cn } from "../../../../lib/cn";
import "./SpotlightCard.css";

export interface SpotlightCardProps extends HTMLAttributes<HTMLElement> {
  as?: "article" | "button" | "div" | "span";
  spotlightColor?: string;
  children?: ReactNode;
}

export default function SpotlightCard({
  as = "div",
  children,
  className,
  onMouseMove,
  spotlightColor = "rgba(255, 255, 255, 0.34)",
  ...props
}: SpotlightCardProps) {
  const elementRef = useRef<HTMLElement>(null);

  const handleMouseMove = (event: MouseEvent<HTMLElement>) => {
    const element = elementRef.current;
    if (element) {
      const rect = element.getBoundingClientRect();
      element.style.setProperty("--mouse-x", `${event.clientX - rect.left}px`);
      element.style.setProperty("--mouse-y", `${event.clientY - rect.top}px`);
      element.style.setProperty("--spotlight-color", spotlightColor);
    }
    onMouseMove?.(event);
  };

  return createElement(
    as,
    {
      ...props,
      ref: elementRef,
      className: cn("card-spotlight", className),
      onMouseMove: handleMouseMove,
    },
    children,
  );
}
